    assert (B/'evaluation_complete.json').exists();progress();rows=read(B/'target_metrics.csv');source=read(B/'source_transfer_metrics.csv');conditional=read(B/'target_conditional_metrics.csv');common=read(B/'common_update_metrics.csv');t1=read(B/'T1_exploratory_metrics.csv');paired=json.loads((B/'paired_bootstrap.json').read_text());control=json.loads((B/'capacity_information_control_bootstrap.json').read_text());models=model_rows();elig=json.loads((B/'target_eligibility.json').read_text());audit=json.loads((A/'identity_split_audit.json').read_text());support=json.loads((A/'photometric_support.json').read_text())
    primary=[r for r in paired if r['source']=='Mixed' and r['bandset']=='full' and 'stratum' not in r];assert len(primary)==2;success=all(r['outlier_difference_CI95'][1]<0 for r in primary)
